package sem

import "testing"

func TestGoRouteMalformedFallbackDoesNotDuplicateInlineRoutes(t *testing.T) {
	const source = `package main
import "net/http"
func handler(w http.ResponseWriter, r *http.Request) {}
func register(mux *http.ServeMux) {
 mux.HandleFunc("/named", handler)
 mux.HandleFunc("/inline", func(w http.ResponseWriter, r *http.Request) {})
 // router.GET("/comment-only", handler)
 g := e.Group("/prefix-only")
 g.GET("/group-child", handler)
}
func broken(
`
	if got := resolveGoRouteReceivers(source, nil); got.parsed || got.exhausted {
		t.Fatal("fixture must reach the token fallback")
	}
	detail := goRouteRegistrationsDetailed(source, nil)
	if !detail.parseFailed || len(detail.masks) != 1 || detail.masks[0] != [2]int{0, len(source)} {
		t.Fatalf("malformed route recovery must mask the whole generic pass: %+v", detail)
	}
	if len(detail.regs) != 1 || detail.regs[0].Route != "/named" || len(detail.inline) != 0 {
		t.Fatalf("token fallback must emit its named registration only: %+v", detail)
	}
	repo := t.TempDir()
	writeFile(t, repo, "main.go", source)
	snapshot, err := BuildProviderSnapshot(t.Context(), repo, "fallback-review")
	if err != nil {
		t.Fatal(err)
	}
	if len(snapshot.Header.PartialFailures) == 0 {
		t.Fatal("malformed source must report a machine-readable partial failure")
	}
	for _, route := range []string{"/named", "/inline", "/comment-only", "/prefix-only", "/group-child"} {
		count := 0
		for _, relation := range snapshot.Relations {
			if relation.Type == "HANDLES_ROUTE" && relation.ToID == externalID("route", route) {
				count++
			}
		}
		want := 0
		if route == "/named" {
			want = 1
		}
		if count != want {
			t.Errorf("%s: got %d route relations, want %d", route, count, want)
		}
	}
}
package sem

import (
	"fmt"
	"strings"
	"testing"
)

func TestGoRouteBudgetExhaustionReportsSnapshotPartialFailure(t *testing.T) {
	for _, depth := range []int{1, 4000} {
		t.Run(fmt.Sprint(depth), func(t *testing.T) {
			var source strings.Builder
			source.WriteString("package routes\nfunc register(e *Echo) {\n g := e.Group(\"/api\")\n")
			for i := 0; i < depth; i++ {
				fmt.Fprintf(&source, "{ g.GET(\"/x%d\", func(){})\n", i)
			}
			source.WriteString(strings.Repeat("}\n", depth) + "}\n")
			repo := t.TempDir()
			writeFile(t, repo, "routes.go", source.String())
			snapshot, err := BuildProviderSnapshot(t.Context(), repo, "route-budget")
			if err != nil {
				t.Fatal(err)
			}
			found := false
			for _, failure := range snapshot.Header.PartialFailures {
				if failure.Code == "E_GO_ROUTE_BUDGET_EXCEEDED" && failure.FilePath == "routes.go" {
					found = true
					if !strings.Contains(failure.EffectOnCompleteness, "HANDLES_ROUTE") || failure.Detail == "" {
						t.Fatalf("loss is not explained: %+v", failure)
					}
				}
			}
			if found != (depth == 4000) {
				t.Fatalf("budget warning=%v at depth %d: %+v", found, depth, snapshot.Header.PartialFailures)
			}
			routes := 0
			for _, relation := range snapshot.Relations {
				if relation.Type == "HANDLES_ROUTE" {
					routes++
				}
			}
			if depth == 1 && routes != 1 {
				t.Fatalf("control lost its route: %d", routes)
			}
			if depth == 4000 && routes != 0 {
				t.Fatalf("exhausted analysis guessed %d routes", routes)
			}
		})
	}
}

